from pathlib import Path

root = Path(__file__).resolve().parents[1] / 'outputs' / 'learning-grove'
p = root / 'static' / 'app.js'
s = p.read_text(encoding='utf-8')
s = s.replace("const contextKey = () => currentTree() && currentNode() ? currentTree().id + '/' + currentNode().id : '';", """const currentCard = () => { const n=currentNode(); return n?.cards[Math.min(n.page||0,Math.max(0,n.cards.length-1))]; };
const contextKey = () => currentTree() && currentNode() ? currentTree().id + '/' + currentNode().id + '/' + (currentCard()?.id||'empty') : '';
const questionOpen = new Set(), scrollPositions = new Map();
let readerObserver, pendingPosition;
function keepReaderPosition(){if(route()[0]==='tree'&&currentTree()){const key=contextKey();scrollPositions.set(key,window.scrollY||0);try{sessionStorage.setItem('grove-reader-scroll:'+key,String(window.scrollY||0));}catch{}}}
function restoreReaderPosition(){const key=contextKey();let y=scrollPositions.get(key);try{y??=Number(sessionStorage.getItem('grove-reader-scroll:'+key)||0);}catch{}requestAnimationFrame(()=>window.scrollTo(0,y||0));}
""")
s=s.replace("skipped:'已跳过'", "skipped:'已跳过',read:'已浏览'")
s=s.replace("  const [page]=route();", "  const [page]=route();\n  document.body.classList.toggle('focus-reading',page==='tree'&&!!currentTree());\n  readerObserver?.disconnect();")
s=s.replace("n.status==='done'", "['done','read'].includes(n.status)")
start=s.index('function renderTree() {')
end=s.index('function field(',start)
s=s[:start]+r'''
function renderTree() {
  const tree=currentTree(),node=currentNode(),cards=node.cards,index=tree.nodes.indexOf(node);
  const page=Math.min(node.page||0,Math.max(0,cards.length-1)),card=cards[page],key=contextKey();
  const messages=node.messages.filter(m=>card&&m.card_id===card.id),legacy=node.messages.filter(m=>!m.card_id);
  const last=cards.length&&page===cards.length-1,next=tree.nodes[index+1];
  const question=card&&/思考|想一想|问题|练习/.test(card.kind||'');
  const answerHtml=items=>items.map(m=>`<article class="reader-message ${m.role==='user'?'user':'assistant'}"><div class="message-author">${m.role==='user'?'你的小问题':'知枝'}${m.card_title?' <span>· '+esc(m.card_title)+'</span>':''}</div><div>${esc(m.content)}</div></article>`).join('');
  $('#main').innerHTML=`<div class="pocket-reader"><header class="pocket-header"><a class="round-control" href="#home" aria-label="返回学习空间">${icon('back',20)}</a><div class="pocket-heading"><span>${esc(tree.title)}</span><strong>${esc(node.title)}</strong></div><details class="pocket-menu"><summary class="round-control" aria-label="更多学习功能">${icon('more',22)}</summary><div class="pocket-menu-sheet"><span class="menu-caption">这一段学习</span><a href="#map/${tree.id}/${node.id}">${icon('tree')}学习树全景</a><button data-action="tree-details">${icon('settings')}学习约定</button><button data-action="branch">${icon('branch')}延伸探索</button><button data-action="link">${icon('link')}关联旧知识</button>${card?`<button data-action="image">${icon('image')}添加图片</button>${card.image?'<button data-action="remove-image">移除图片</button>':''}`:''}<button data-action="refill">补充卡片</button><button data-action="skip">暂时跳过本节</button><button data-action="settings">模型设置</button><a href="#profile">个人资料库</a><button data-action="export">导出学习档案</button><button class="danger" data-action="delete-tree">删除学习树</button></div></details></header>
  <section class="reader-sheet ${question?'is-thought':''}" aria-label="当前知识卡片"><div class="sheet-topline"><span class="sheet-category">${esc(card?.kind||'新的知识点')}</span><span class="sheet-folio">${cards.length?String(page+1).padStart(2,'0'):'—'}<small> / ${String(cards.length).padStart(2,'0')}</small></span></div><article class="sheet-content" ${card?`data-card-id="${card.id}"`:''}>${card?`<div class="sheet-sprout">${icon(question?'chat':'tree',24)}</div><h1>${esc(card.title)}</h1><div class="sheet-body">${esc(card.text)}</div>${card.image?`<figure><img src="${esc(card.image)}" alt="本页知识卡片附图"></figure>`:''}`:`<div class="empty-sprout">${icon('tree',44)}</div><h1>${esc(node.title)}</h1><p class="sheet-body">${esc(node.description||'先有一个方向，再慢慢读懂。')}</p><button class="primary" data-action="generate-node">展开这一节 ${icon('arrow',16)}</button>`}</article><div class="sheet-footnote"><span>${tree.demo?'固定示例 · 不调用模型':'随时停下，也随时接着看'}</span><span class="leaf-dots" aria-hidden="true">${cards.map((_,i)=>`<i class="${i===page?'active':''}"></i>`).join('')}</span></div></section>
  <nav class="pocket-controls" aria-label="卡片阅读操作"><button class="round-control" data-action="page" data-page="${Math.max(0,page-1)}" ${page===0?'disabled':''} aria-label="上一页">${icon('back',20)}</button><button class="ask-pill" data-action="toggle-question" aria-expanded="${questionOpen.has(key)}" aria-controls="reader-question">${icon('chat',17)}问一问${messages.length?'<span class="question-count">'+Math.ceil(messages.length/2)+'</span>':''}<span class="ask-chevron">⌄</span></button>${cards.length?last?`<button class="next-chapter" data-action="advance">${next?'继续下一节':'收好这段学习'}${icon('arrow',17)}</button>`:`<button class="round-control next-page" data-action="page" data-page="${page+1}" aria-label="下一页">${icon('arrow',20)}</button>`:'<span></span>'}</nav>
  <div class="question-reveal"><span></span><p>往下看看，留一个小问题</p></div><details id="reader-question" class="reader-question" ${questionOpen.has(key)?'open':''}><summary><span>${icon('chat',18)} 想问什么，都可以</span><span class="question-fold">收起 / 展开</span></summary><div class="question-inner"><p class="question-note">上面的卡片一直在。往上翻可以对照，往下看回答。</p><div class="chat-chips"><button data-action="chat-chip" data-value="换一个生活中的例子解释一下。">换个例子</button><button data-action="chat-chip" data-value="这与前一张卡片有什么联系？">联系上一张</button><button data-action="chat-chip" data-value="我想先自己想一想，请给我一点提示。">一点提示</button></div><form id="chat-form" class="chat-form"><textarea name="message" aria-label="向学习助手提问" placeholder="这一页，哪里让你好奇？" required maxlength="4000">${esc(chatDrafts.get(key)||'')}</textarea><div class="send-row"><span>记在这张卡片里，理解会连起来</span><button class="primary" type="submit">发送 ${icon('arrow',16)}</button></div></form><div class="reader-answers" role="log" aria-label="这张卡片的问答">${messages.length?answerHtml(messages):'<p class="answer-empty">问题不必完整，从一点好奇开始就好。</p>'}</div>${legacy.length?`<details class="legacy-questions"><summary>本知识点以前的交流 · ${legacy.length} 条</summary>${answerHtml(legacy)}</details>`:''}</div></details><footer class="pocket-footer"><span id="reader-save-state">位置已记好，下次从这里继续</span><a href="#home">先看到这里 ${icon('check',13)}</a></footer></div>`;
  const section=$('#reader-question');
  section.addEventListener('toggle',()=>{if(section.open)questionOpen.add(key);else questionOpen.delete(key);const b=$('[data-action="toggle-question"]');if(b)b.setAttribute('aria-expanded',String(section.open));});
  if(typeof IntersectionObserver!=='undefined'){
    readerObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&window.scrollY>35&&!section.open&&!section.dataset.manualClose){section.open=true;questionOpen.add(key);}},{threshold:.7});
    readerObserver.observe($('.question-reveal'));
  }
}
async function changeCard(page){keepReaderPosition();const t=currentTree(),n=currentNode();const r=await act({type:'set_page',tree_id:t.id,node_id:n.id,page},false);if(r){questionOpen.delete(contextKey());render();window.scrollTo(0,0);keepReaderPosition();}}
async function advanceReading(){const t=currentTree(),n=currentNode();const r=await act({type:'advance',tree_id:t.id,node_id:n.id},false);if(!r)return;if(r.next_node_id){await openNode(r.next_node_id);const next=currentNode();if(next&&!next.ready&&(t.demo||config.enabled))await act({type:'refill',tree_id:t.id,node_id:next.id});}else{go('map/'+t.id+'/'+n.id);toast('读过的都记下了。想回顾时，随时回来。');}}
''' + s[end:]
s=s.replace("else if(action==='page')await act({type:'set_page',tree_id:t.id,node_id:n.id,page:Number(b.dataset.page)});", """else if(action==='page')await changeCard(Number(b.dataset.page));
  else if(action==='advance')await advanceReading();
  else if(action==='toggle-question'){const section=$('#reader-question');section.open=!section.open;if(section.open){questionOpen.add(contextKey());section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});}else{section.dataset.manualClose='1';questionOpen.delete(contextKey());window.scrollTo({top:0,behavior:'smooth'});}}""")
s=s.replace("else if(form.id==='chat-form'){const key=contextKey();historyOpen.add(key);const r=await act({type:'chat',tree_id:t.id,node_id:n.id,card_id:n.cards[n.page||0]?.id||'',message:f.get('message')},false);if(r){chatDrafts.delete(key);render();$('#chat-form textarea')?.focus();}}", """else if(form.id==='chat-form'){const key=contextKey(),message=f.get('message');chatDrafts.set(key,message);questionOpen.add(key);const y=window.scrollY;const button=form.querySelector('[type="submit"]');if(button)button.textContent='正在想…';const r=await act({type:'chat',tree_id:t.id,node_id:n.id,card_id:currentCard()?.id||'',message},false);if(r){chatDrafts.delete(key);if(contextKey()===key){render();window.scrollTo(0,y);$('#reader-question').open=true;requestAnimationFrame(()=>$('.reader-answers')?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'}));}else render();}else if(button)button.innerHTML='再试一次 '+icon('arrow',16);}""")
s=s.replace("window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});", """window.addEventListener('hashchange',()=>{render();if(route()[0]==='tree')restoreReaderPosition();else window.scrollTo(0,0);});
window.addEventListener('scroll',keepReaderPosition,{passive:true});
window.addEventListener('pagehide',keepReaderPosition);
document.addEventListener('pointerdown',event=>{const control=event.target.closest('button,.round-control,.ask-pill,a.primary,summary');if(!control||control.disabled||matchMedia('(prefers-reduced-motion: reduce)').matches)return;control.classList.remove('jelly-tap');void control.offsetWidth;control.classList.add('jelly-tap');control.addEventListener('animationend',()=>control.classList.remove('jelly-tap'),{once:true});});
""")
s=s.replace("state=result.state;config=result.settings;render();}).catch", "state=result.state;config=result.settings;render();if(route()[0]==='tree')restoreReaderPosition();}).catch")
